;; curriculum: Fourier-Analysis (undergrad / early grad) — harmonic decomposition; prerequisites: sine, taylor, series
;; math target: a flat road plus sine harmonics builds a square wave; each term is 4/π · sin(nx)/n for odd n.

app riya-level-fourier "1.1.0"
"riya level 28 · Fourier — flat road + harmonics = square wave. Collect +sin(x), +sin(3x)/3, +sin(5x)/5 and watch the road synthesize into a staircase. Ride the synthesized shape to the star! Composed from std-platformer-body + std-objective-flow + std-fx-particles + std-pickup + std-tutorial-overlay, rendered through math-canvas so the components, the sum and the target square wave stay visible. Rebound into the riya-game-platformer organism (menu + all worlds)."

;; @exposure internal

orbital RiyaFourierOrbital {
  uses Body from "std/behaviors/std-platformer-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Pickup from "std/behaviors/std-pickup"
  uses Tutorial from "std/behaviors/std-tutorial-overlay"
  uses Genre from "std/behaviors/std-platformer-puzzle"

  type RiyaFourierBody = {
    x : number!
    y : number!
    width : number!
    height : number!
    vx : number
    vy : number
    grounded : boolean
    facingRight : boolean
  }
  type RiyaFourierPlatform = {
    id : string
    x : number!
    y : number!
    width : number!
    height : number!
    type : "ground" | "platform" | "hazard" | "goal"
  }
  type RiyaFourierFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
    animation : string
  }
  type RiyaFourierPickup = {
    id : string!
    x : number!
    y : number!
    kind : string!
    glyph : string
    message : string
    collected : boolean
  }
  type RiyaFourierCurveSample = {
    x : number!
    y : number!
  }
  type RiyaFourierCurve = {
    label : string
    color : string
    samples : [RiyaFourierCurveSample]!
    dash : "dashed" | "dotted"
  }
  type RiyaFourierGuide = {
    kind : "vline" | "hline"!
    at : number!
    color : string
    dash : "dashed" | "dotted"
    label : string
  }
  type RiyaFourierHarmonic = {
    n : number!
    label : string
  }
  type RiyaFourierFxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    vy : number
    animation : string
  }

  entity RiyaFourierState [runtime, shared] {
    id : string!
    active : boolean = false
    body : RiyaFourierBody = { x: -8, y: 2.5, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
    fell : boolean = false
    hazardId : string = ""
    goalId : string = ""
    skating : boolean = false
    pickups : [RiyaFourierPickup] = []
    pickupCompleted : boolean = false
    total : number = 0
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaFourierFx] = []
    celebrated : boolean = false
    harmonics : [RiyaFourierHarmonic] = []
    zoneId : string = "fourier"
    platforms : [RiyaFourierPlatform] = []
    guides : [RiyaFourierGuide] = []
    baseCurves : [RiyaFourierCurve] = []
    harmonicCurves : [RiyaFourierCurve] = []
    targetSquareWave : [RiyaFourierCurveSample] = []
    sumSamples : [RiyaFourierCurveSample] = []
  }

  entity FourierTutorialData [runtime] {
    id : string!
    step : number = 0
    done : boolean = false
  }

  trait FourierBody = Body.traits.PlatformerBody -> RiyaFourierState {
    events {
      STEER: FOURIER_STEER
      JUMP: FOURIER_LEAP
      PLACE: FOURIER_PLACE
      RESTART: FOURIER_RESTART
      CURVE_MOD_ADD: FOURIER_CURVE_MOD_ADD
      BODY_JUMPED: FOURIER_JUMPED
      BODY_LANDED: FOURIER_LANDED
      BODY_HAZARD: FOURIER_HAZARD
      BODY_GOAL: FOURIER_GOAL
      BODY_FELL: FOURIER_FELL
      BODY_SKATE_START: FOURIER_SKATE_ON
      BODY_SKATE_END: FOURIER_SKATE_OFF
      SET_PLATFORMS: FOURIER_SET_PLATFORMS
      SET_SKATE_CURVE: FOURIER_SET_SKATE_CURVE
    }
    config {
      running: true
      spawn: { x: -8, y: 2.5, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
      gravity: -24
      jumpStrength: 11
      moveSpeed: 5
      maxFallSpeed: 14
      xMin: -10
      xMax: 9.4
      killY: -3
      skate: true
      curveModsEnabled: true
      skateSnap: 0.9
    }
  }

  trait FourierGate = Gate.traits.ObjectiveFlow -> RiyaFourierState {
    events {
      PROGRESS: FOURIER_PROGRESS
      GAME_END: FOURIER_GAME_END
      RESTART: FOURIER_RESTART
    }
    config { running: true }
  }

  trait FourierFx = Particles.traits.FxParticles -> RiyaFourierState {
    events {
      BURST: FOURIER_BURST
    }
    config { running: true }
  }

  trait FourierPickup = Pickup.traits.Pickup -> RiyaFourierState {
    events {
      PICKED: FOURIER_PICKED
      COLLECT: FOURIER_COLLECT
      PICKUP_SET_COMPLETED: FOURIER_PICKUP_SET_COMPLETED
      SET_FEATURES: FOURIER_SET_FEATURES
    }
    config {
      running: true
      reachX: 0.7
      reachY: 1.2
    }
  }

  trait FourierLevelData -> @rebindable RiyaFourierState [lifecycle] {
    initial: active

    state active {
      INIT -> active
        (emit RIYA_LEVEL_DATA {
          id: "fourier"
          name: @config.worldName
          equation: @config.equation
          concept: @config.concept
          regionColor: @config.regionColor
          entryY: @config.entryY
          exitY: @config.exitY
          platforms: (array/map @config.platforms (fn p @p))
          stars: (array/map @config.stars (fn s @s))
          skateCurve: (array/map @config.skateCurve (fn s @s))
          baseCurves: (array/map @config.baseCurves (fn c @c))
          harmonicCurves: (array/map @config.harmonicCurves (fn c @c))
          targetSquareWave: (array/map @config.targetSquareWave (fn s @s))
          sumSamples: (array/map @config.sumSamples (fn s @s))
          guides: (array/map @config.guides (fn g @g))
        })
    }

    emits {
      RIYA_LEVEL_DATA -> external {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaFourierPlatform]!
        stars : [RiyaFourierPickup]!
        skateCurve : [RiyaFourierCurveSample]
        baseCurves : [RiyaFourierCurve]
        harmonicCurves : [RiyaFourierCurve]
        targetSquareWave : [RiyaFourierCurveSample]
        sumSamples : [RiyaFourierCurveSample]
        guides : [RiyaFourierGuide]
      }
        @description "The zone's canonical static geometry + pedagogy, broadcast once on INIT in zone-local coordinates. This atom's own play trait consumes it to seed the body/pickup authorities and the render; the riya open-world organism consumes the same event and applies its zone offset, so standalone and composed can never diverge."
        @tier "domain"
    }

    config {
      worldName : string = "Fourier"
        @label "World Name"
        @description "This world's display name — the open world's zone banner reads it from RIYA_LEVEL_DATA."
        @tier "presentation"
      equation : string = "y = 1 + Σ sin(nx)/n"
        @label "Equation"
        @description "The zone's skate/banner equation."
        @tier "presentation"
      concept : string = "a flat road plus sine harmonics builds a square-wave staircase — Fourier synthesis as terrain"
        @label "Concept"
        @description "The world's one math idea."
        @tier "presentation"
      regionColor : string = "#38bdf8"
        @label "Region Color"
        @description "Zone band accent in the open world."
        @tier "presentation"
      entryY : number = 1.1
        @label "Entry Y"
        @description "Run-surface height at the zone's left edge; the open world stitches its incoming bridge to this."
        @tier "domain"
      exitY : number = 1.1
        @label "Exit Y"
        @description "Run-surface height at the zone's right edge; the open world stitches its outgoing bridge to this."
        @tier "domain"
      platforms : [RiyaFourierPlatform] = [
        { id: "f0", x: -10, y: -2, width: 2, height: 3.1, type: "ground" }
        { id: "f1", x: -8, y: -2, width: 2, height: 3.1, type: "ground" }
        { id: "f2", x: -6, y: -2, width: 2, height: 3.1, type: "ground" }
        { id: "f3", x: -4, y: -2, width: 2, height: 3.1, type: "ground" }
        { id: "f4", x: -2, y: -2, width: 2, height: 3.1, type: "ground" }
        { id: "f5", x: 0, y: -2, width: 2, height: 3.1, type: "ground" }
        { id: "f6", x: 2, y: -2, width: 2, height: 3.1, type: "ground" }
        { id: "f7", x: 4, y: -2, width: 2, height: 3.1, type: "ground" }
        { id: "f8", x: 6, y: -2, width: 2, height: 3.1, type: "ground" }
        { id: "f9", x: 8, y: -2, width: 2, height: 3.1, type: "ground" }
      ]
        @label "Platforms"
        @description "Canonical terrain — seeds the body authority's collision AND the canvas bars via RIYA_LEVEL_DATA. A flat road of ten equal tiles the harmonics rebuild into a square-wave staircase."
        @tier "domain"
      stars : [RiyaFourierPickup] = [
        { id: "s1", x: -7, y: 2.5, kind: "star", glyph: "★", message: "" }
        { id: "s2", x: -3, y: 2.5, kind: "star", glyph: "★", message: "" }
        { id: "s3", x: 2.5, y: 2.5, kind: "star", glyph: "★", message: "" }
