  trait FourierTutorialPreview -> FourierTutorialData [interaction, instance] {
    initial: idle
    state idle {
      INIT -> idle
        (render-ui center null)
    }
  }

  trait FourierTutorial = Tutorial.traits.TutorialOverlay -> FourierTutorialData {
    events {
      SHOW: FOURIER_TUTORIAL_SHOW
      TUTORIAL_DONE: FOURIER_TUTORIAL_DONE
    }
    config {
      autoShow: true
      previewTrait: @trait.FourierTutorialPreview
      steps: [
        { id: "intro", title: "Fourier", body: "A flat road y = 1 plus sine harmonics becomes a square-wave staircase. Grab harmonic pads to add terms, then ride the sum to every ★." }
      ]
    }
  }

  trait RiyaFourierGenre = Genre.traits.PlatformerPuzzle -> RiyaFourierState {
    config {
      agencyTrait: @trait.FourierBody
      challengeTrait: @trait.FourierBody
      goalTrait: @trait.FourierGate
      rewardTrait: @trait.FourierPickup
      feedbackTrait: @trait.FourierFx
    }
  }

  trait RiyaFourierPlay -> @rebindable RiyaFourierState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.active true)
        (set @entity.celebrated false)
        (set @entity.score 0)
        (emit FOURIER_RESTART { id: "board" })
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            keyMap: { ArrowLeft: "FOURIER_LEFT", KeyA: "FOURIER_LEFT", ArrowRight: "FOURIER_RIGHT", KeyD: "FOURIER_RIGHT", ArrowUp: "FOURIER_JUMP", KeyW: "FOURIER_JUMP", Space: "FOURIER_JUMP" }
            keyUpMap: { ArrowLeft: "FOURIER_STOP", KeyA: "FOURIER_STOP", ArrowRight: "FOURIER_STOP", KeyD: "FOURIER_STOP" }
            curves: (array/concat
              @entity.baseCurves
              (array/filter @entity.harmonicCurves (fn c (array/find @entity.harmonics (fn h (== (object/get @h n) (object/get @c n))))))
              [ { label: "target square wave", color: "#94a3b8", samples: @entity.targetSquareWave, dash: "dashed" } ]
              [ { label: "synthesized road", color: (if @entity.skating @config.curveSkateColor @config.curveColor), samples: (array/map @entity.sumSamples (fn s
                (let ((x (object/get @s x)))
                (let ((y (+ 1
                  (if (array/find @entity.harmonics (fn h (== (object/get @h n) 1))) (* 1.2732 (math/sin @x)) 0)
                  (if (array/find @entity.harmonics (fn h (== (object/get @h n) 3))) (* 0.4244 (math/sin (* 3 @x))) 0)
                  (if (array/find @entity.harmonics (fn h (== (object/get @h n) 5))) (* 0.2546 (math/sin (* 5 @x))) 0))))
                { x: @x, y: @y })))) } ])
            guides: @entity.guides
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "star") @config.starColor "#f472b6"), radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                  (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] []))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })
        (render-ui hud-bottom {
          type: stack
          direction: horizontal
          justify: start
          className: "p-4"
          children: [ { type: control-grid, kind: "dpad", visibility: "auto", directionEvents: { left: "FOURIER_LEFT", right: "FOURIER_RIGHT", up: "FOURIER_JUMP" }, directionReleaseEvents: { left: "FOURIER_STOP", right: "FOURIER_STOP" } } ]
        })

      RIYA_LEVEL_DATA -> idle when (== @payload.id "fourier")
        (set @entity.guides @payload.guides)
        (set @entity.baseCurves @payload.baseCurves)
        (set @entity.harmonicCurves @payload.harmonicCurves)
        (set @entity.targetSquareWave @payload.targetSquareWave)
        (set @entity.sumSamples @payload.sumSamples)
        (set @entity.objectivesLeft (array/len @payload.stars))
        (emit FOURIER_SET_PLATFORMS { platforms: @payload.platforms })
        (emit FOURIER_SET_SKATE_CURVE { curve: @payload.skateCurve })
        (emit FOURIER_SET_FEATURES { features: @payload.stars })

      FOURIER_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit FOURIER_STEER { dir: -1 })

      FOURIER_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit FOURIER_STEER { dir: 1 })

      FOURIER_STOP -> idle when (== @entity.active true)
        (emit FOURIER_STEER { dir: 0 })

      FOURIER_JUMP -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit FOURIER_LEAP {})

      FOURIER_FELL -> idle when (== @entity.active true)
        (emit FOURIER_PLACE { x: @config.respawnX, y: @config.respawnY })
        (emit FOURIER_BURST { particles: (array/map [ "fx-fourier-fell" ] (fn fid { id: @fid, type: "info", x: @config.respawnX, z: @config.respawnY, message: "💫", ttl: 3 })) })

      FOURIER_SKATE_ON -> idle when (== @entity.active true)
        (emit FOURIER_BURST { particles: (array/concat
          {
            id: "narrative-skate",
            type: "narrative",
            x: @entity.body.x,
            z: (+ @entity.body.y 2),
            y: 0,
            message: "riding the synthesized sum",
            ttl: 2,
            maxTtl: 2,
            bornAt: (time/now),
            space: "world",
            effect: "float-text",
            color: "#38bdf8",
            size: 0.7,
            vx: 0,
            vy: 0,
            vz: 0,
            particleCount: 1
          }
          {
            id: "fx-fourier-skate",
            type: "info",
            x: @payload.x,
            z: (+ @payload.y 0.6),
            y: 0,
            message: (str/concat @config.equationText " · x = " (math/round (+ @payload.x 0.3) 1)),
            ttl: 4
          }
        ) })

      FOURIER_PICKED -> idle when (== @entity.active true)
        (emit FOURIER_BURST { particles: (array/map [ "fx-pickup-" ] (fn fid { id: (str/concat @fid @payload.id), type: "pickup", x: @payload.x, z: @payload.y, message: (object/get @payload glyph), ttl: 2 })) })
      FOURIER_COLLECT -> idle when (== @entity.active true)
        (set @entity.score @payload.total)
        (set @entity.objectivesLeft (- (array/len @entity.pickups) @payload.total))
        (emit FOURIER_PROGRESS { objectivesLeft: @entity.objectivesLeft, movesLeft: 9999 })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })

      FOURIER_PICKUP_SET_COMPLETED -> idle when (== @entity.active true)
        (emit FOURIER_BURST { particles: (array/map [ "complete" ] (fn _ { id: "narrative-complete", type: "narrative", x: 0, z: 8, y: 0, message: "square wave = 4/π Σ sin(nx)/n", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#facc15", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
        (emit FOURIER_PROGRESS { objectivesLeft: 0, movesLeft: 9999 })
      FOURIER_GAME_END -> idle when (and (== @payload.result "won") (== @entity.celebrated false))
        (set @entity.celebrated true)
        (emit RIYA_LEVEL_SOLVED { level: "fourier" })

      FOURIER_TUTORIAL_DONE -> idle
        (emit FOURIER_BURST { particles: (array/map [ "tutorial" ] (fn _ { id: "narrative-tutorial", type: "narrative", x: 0, z: 10, y: 0, message: "sines can build a square wave", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#38bdf8", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
    }

    ticks {
      renderTick every 100ms when (== @entity.active true)
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            keyMap: { ArrowLeft: "FOURIER_LEFT", KeyA: "FOURIER_LEFT", ArrowRight: "FOURIER_RIGHT", KeyD: "FOURIER_RIGHT", ArrowUp: "FOURIER_JUMP", KeyW: "FOURIER_JUMP", Space: "FOURIER_JUMP" }
            keyUpMap: { ArrowLeft: "FOURIER_STOP", KeyA: "FOURIER_STOP", ArrowRight: "FOURIER_STOP", KeyD: "FOURIER_STOP" }
            curves: (array/concat
              @entity.baseCurves
              (array/filter @entity.harmonicCurves (fn c (array/find @entity.harmonics (fn h (== (object/get @h n) (object/get @c n))))))
              [ { label: "target square wave", color: "#94a3b8", samples: @entity.targetSquareWave, dash: "dashed" } ]
              [ { label: "synthesized road", color: (if @entity.skating @config.curveSkateColor @config.curveColor), samples: (array/map @entity.sumSamples (fn s
                (let ((x (object/get @s x)))
                (let ((y (+ 1
                  (if (array/find @entity.harmonics (fn h (== (object/get @h n) 1))) (* 1.2732 (math/sin @x)) 0)
                  (if (array/find @entity.harmonics (fn h (== (object/get @h n) 3))) (* 0.4244 (math/sin (* 3 @x))) 0)
                  (if (array/find @entity.harmonics (fn h (== (object/get @h n) 5))) (* 0.2546 (math/sin (* 5 @x))) 0))))
                { x: @x, y: @y })))) } ])
            guides: @entity.guides
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "star") @config.starColor "#f472b6"), radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                  (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] []))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
    }

    emits {
      FOURIER_LEFT -> external {
        id : string
      }
        @description "Run-left intent from ArrowLeft/KeyA keydown or d-pad (forwarded as STEER dir −1)."
        @tier "domain"
      FOURIER_RIGHT -> external {
        id : string
      }
        @description "Run-right intent from ArrowRight/KeyD keydown or d-pad (forwarded as STEER dir +1)."
        @tier "domain"
      FOURIER_STOP -> external {
        id : string
      }
        @description "Left/right key release (keyUpMap or d-pad release); forwarded as STEER dir 0."
        @tier "domain"
      FOURIER_JUMP -> external {
        id : string
      }
        @description "Jump intent from Space/ArrowUp/KeyW or d-pad up; forwarded as the body authority's renamed JUMP (FOURIER_LEAP), which accepts it only while grounded."
        @tier "domain"
      FOURIER_STEER -> external {
        dir : number!
      }
        @description "Renamed STEER consumed by this world's platformer-body authority (−1/0/+1 × moveSpeed)."
        @tier "domain"
      FOURIER_LEAP -> external {
        id : string
      }
        @description "Renamed JUMP consumed by this world's platformer-body authority (grounded-gated vertical kick)."
        @tier "domain"
      FOURIER_PLACE -> external {
        x : number!
        y : number!
      }
        @description "Renamed PLACE consumed by this world's platformer-body authority; the pit-fall respawn teleport."
        @tier "domain"
      FOURIER_FELL -> external {
        x : number!
        y : number!
      }
        @description "Pit-fall signal from this world's platformer-body authority (renamed BODY_FELL); respawns riya at her spawn with every star kept."
        @tier "domain"
      FOURIER_SKATE_ON -> external {
        x : number!
        y : number!
        slope : number!
      }
        @description "Skate-engage signal from this world's platformer-body authority (renamed BODY_SKATE_START); riya touched the synthesized road — fires the equation fx burst."
        @tier "domain"
      FOURIER_PICKED -> external {
        id : string!
        kind : string!
        x : number!
        y : number!
        glyph : string
        message : string
      }
        @description "A pickup was collected (renamed PICKED from std-pickup); the play trait bursts the pickup glyph, the challenge trait stacks the harmonic's curve mods and narrative beats."
        @tier "domain"
      FOURIER_COLLECT -> external {
        total : number!
      }
        @description "Running pickup count (renamed COLLECT from std-pickup); updates score/objectives and forwards to the objective-flow gate."
        @tier "domain"
      FOURIER_PICKUP_SET_COMPLETED -> external {
      }
        @description "Every pickup in the set is collected (renamed PICKUP_SET_COMPLETED from std-pickup)."
        @tier "domain"
      FOURIER_RESTART -> external {
        id : string
      }
        @description "Reseed broadcast consumed by this world's platformer-body/objective-flow/pickup authorities (renamed RESTART)."
        @tier "domain"
      FOURIER_BURST -> external {
        particles : [RiyaFourierFx]
      }
        @description "Particle batch spawned on star pickup, boost pickup, pit respawn or tutorial dismiss; fx-particles fades it."
        @tier "domain"
      FOURIER_PROGRESS -> external {
        objectivesLeft : number!
        movesLeft : number!
      }
        @description "Sparse progress signal emitted by the Play trait; the objective-flow gate resolves won from it."
        @tier "domain"
      FOURIER_GAME_END -> external {
        result : string!
      }
        @description "Win-gate resolution from this world's objective-flow authority (renamed GAME_END); won clears the level."
        @tier "domain"
      RIYA_LEVEL_SOLVED -> external {
        level : string
      }
        @description "Every ★ captured — the win gate resolved won (guarded by celebrated so the gate's repeated GAME_ENDs fire it once)."
        @tier "domain"
      FOURIER_SET_PLATFORMS -> external {
        platforms : [RiyaFourierPlatform]!
      }
        @description "Renamed SET_PLATFORMS consumed by this world's platformer-body authority; forwards the canonical RIYA_LEVEL_DATA terrain to collision."
        @tier "domain"
      FOURIER_SET_SKATE_CURVE -> external {
        curve : [RiyaFourierCurveSample]!
      }
        @description "Renamed SET_SKATE_CURVE consumed by this world's platformer-body authority; forwards the canonical RIYA_LEVEL_DATA skate surface."
        @tier "domain"
      FOURIER_SET_FEATURES -> external {
        features : [RiyaFourierPickup]!
      }
        @description "Renamed SET_FEATURES consumed by this world's pickup authority; forwards the canonical RIYA_LEVEL_DATA stars and harmonic pads."
        @tier "domain"
    }

    listens {
      FOURIER_TUTORIAL_DONE { id : string }
      RIYA_LEVEL_DATA {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaFourierPlatform]!
        stars : [RiyaFourierPickup]!
        skateCurve : [RiyaFourierCurveSample]
        baseCurves : [RiyaFourierCurve]
        harmonicCurves : [RiyaFourierCurve]
        targetSquareWave : [RiyaFourierCurveSample]
        sumSamples : [RiyaFourierCurveSample]
        guides : [RiyaFourierGuide]
      }
    }

    config {
      equationText : string = "y = 1 + Σ sin(nx)/n"
        @label "Equation Text"
        @description "Equation of this world's synthesized road, shown by the skate fx burst."
        @tier "presentation"
      equationColor : string = "#7dd3fc"
        @label "Equation Color"
        @description "Color of the floating equation label that follows riya while she skates."
        @tier "presentation"
      curveColor : string = "#38bdf8"
        @label "Curve Color"
        @description "Color of the synthesized road curve when riya is not skating it."
        @tier "presentation"
      curveSkateColor : string = "#f0abfc"
        @label "Curve Skate Color"
        @description "Color of the synthesized road curve while riya is skating it."
        @tier "presentation"
      respawnX : number = -8
        @label "Respawn X"
        @description "X riya teleports to after a pit fall (matches FourierBody spawn.x)."
        @tier "domain"
      respawnY : number = 2.5
        @label "Respawn Y"
        @description "Y riya teleports to after a pit fall (matches FourierBody spawn.y)."
        @tier "domain"
      reachRadius : number = 0.7
        @label "Reach Radius"
        @description "Legacy reach distance; std-pickup uses its own reachX/reachY."
        @tier "domain"
      objectiveText : string = ""
        @label "Objective Text"
        @description "HUD objective text — intentionally empty; the curves and the synthesizing road carry the objective."
        @tier "presentation"
      worldName : string = "Fourier"
        @label "World Name"
        @description "This world's display name, shown in the game-shell title chip as \"riya · <worldName>\"."
        @tier "presentation"
      showTelemetry : boolean = false
        @label "Show Telemetry"
        @description "When true, draws a compact x/y/v readout on the canvas near riya (teaching/debug aid). Off keeps the HUD to score only."
        @tier "domain"
      arrowOffsetY : number = 1.9
        @label "Arrow Offset Y"
        @description "World units above the body center where the velocity vector arrow originates, so it floats above the player sprite."
        @tier "presentation"
      arrowScale : number = 0.5
        @label "Arrow Scale"
        @description "Scale factor for the velocity vector arrow, kept short so it does not dip behind the sprite."
        @tier "presentation"
      fxPresets : [RiyaFourierFxPreset] = [ { type: "info", color: "#38bdf8", color2: "#0c4a6e", size: 0.8, shape: "puff", count: 4 }, { type: "pickup", color: "#ffe066", color2: "#ffffff", size: 1.0, shape: "spark", count: 5, glow: 0.12, vy: -0.1 }, { type: "narrative", color: "#38bdf8", size: 1.4, shape: "ring", count: 1, glow: 0.1 } ]
        @label "Fx Presets"
        @description "Look table for world-space particle effects rendered by the draw-fx-layer."
        @tier "presentation"
      conceptText : string = "a flat road plus sine harmonics builds a square-wave staircase — Fourier synthesis as terrain"
        @label "Concept Text"
