        @tier "presentation"
      yMax : number = 12
        @label "Y Max"
        @description "Top edge of the visible math window."
        @tier "presentation"
      width : number = 800
        @label "Canvas Width"
        @description "math-canvas display width in px."
        @tier "presentation"
      height : number = 480
        @label "Canvas Height"
