  }

  trait FourierChallenge -> @rebindable RiyaFourierState [game-core, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.harmonics [])

      FOURIER_PICKED -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (if (str/endsWith @payload.id "h1")
          (do
            (emit FOURIER_CURVE_MOD_ADD { x0: -3.1416, x1: 0, a: 1, h: 0, k: -1.2732 })
            (emit FOURIER_CURVE_MOD_ADD { x0: 0, x1: 3.1416, a: 1, h: 0, k: 1.2732 })
            (set @entity.harmonics (array/append @entity.harmonics { n: 1, label: "+sin(x)" }))
            (emit FOURIER_BURST { particles: (array/concat
              { id: "narrative-h1-fact", type: "narrative", x: -5, z: 4.5, y: 0, message: "+sin(x)", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 }
              { id: "narrative-h1-hint", type: "narrative", x: -5, z: 5, y: 0, message: "first harmonic", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }
            ) }))
          (if (str/endsWith @payload.id "h3")
            (do
              (emit FOURIER_CURVE_MOD_ADD { x0: -3.1416, x1: -2.0944, a: 1, h: 0, k: -0.4244 })
              (emit FOURIER_CURVE_MOD_ADD { x0: -2.0944, x1: -1.0472, a: 1, h: 0, k: 0.4244 })
              (emit FOURIER_CURVE_MOD_ADD { x0: -1.0472, x1: 0, a: 1, h: 0, k: -0.4244 })
              (emit FOURIER_CURVE_MOD_ADD { x0: 0, x1: 1.0472, a: 1, h: 0, k: 0.4244 })
              (emit FOURIER_CURVE_MOD_ADD { x0: 1.0472, x1: 2.0944, a: 1, h: 0, k: -0.4244 })
              (emit FOURIER_CURVE_MOD_ADD { x0: 2.0944, x1: 3.1416, a: 1, h: 0, k: 0.4244 })
              (set @entity.harmonics (array/append @entity.harmonics { n: 3, label: "+sin(3x)/3" }))
              (emit FOURIER_BURST { particles: (array/concat
                { id: "narrative-h3-fact", type: "narrative", x: -2, z: 4, y: 0, message: "+sin(3x)/3", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 }
                { id: "narrative-h3-hint", type: "narrative", x: -2, z: 4.5, y: 0, message: "third harmonic", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }
              ) }))
            (if (str/endsWith @payload.id "h5")
              (do
                (emit FOURIER_CURVE_MOD_ADD { x0: -3.1416, x1: -2.5133, a: 1, h: 0, k: -0.2546 })
                (emit FOURIER_CURVE_MOD_ADD { x0: -2.5133, x1: -1.885, a: 1, h: 0, k: 0.2546 })
                (emit FOURIER_CURVE_MOD_ADD { x0: -1.885, x1: -1.2566, a: 1, h: 0, k: -0.2546 })
                (emit FOURIER_CURVE_MOD_ADD { x0: -1.2566, x1: -0.6283, a: 1, h: 0, k: 0.2546 })
                (emit FOURIER_CURVE_MOD_ADD { x0: -0.6283, x1: 0, a: 1, h: 0, k: -0.2546 })
                (emit FOURIER_CURVE_MOD_ADD { x0: 0, x1: 0.6283, a: 1, h: 0, k: 0.2546 })
                (emit FOURIER_CURVE_MOD_ADD { x0: 0.6283, x1: 1.2566, a: 1, h: 0, k: -0.2546 })
                (emit FOURIER_CURVE_MOD_ADD { x0: 1.2566, x1: 1.885, a: 1, h: 0, k: 0.2546 })
                (emit FOURIER_CURVE_MOD_ADD { x0: 1.885, x1: 2.5133, a: 1, h: 0, k: -0.2546 })
                (emit FOURIER_CURVE_MOD_ADD { x0: 2.5133, x1: 3.1416, a: 1, h: 0, k: 0.2546 })
                (set @entity.harmonics (array/append @entity.harmonics { n: 5, label: "+sin(5x)/5" }))
                (emit FOURIER_BURST { particles: (array/concat
                  { id: "narrative-h5-fact", type: "narrative", x: 1, z: 5, y: 0, message: "+sin(5x)/5", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 }
                  { id: "narrative-h5-hint", type: "narrative", x: 1, z: 5.5, y: 0, message: "fifth harmonic", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }
                ) }))
              null)))
    }

    emits {
      FOURIER_CURVE_MOD_ADD -> external {
        x0 : number!
        x1 : number!
        a : number!
        h : number!
        k : number!
      }
        @description "Renamed CURVE_MOD_ADD consumed by the platformer-body authority; harmonic pads rebuild the road by stacking constant-step approximations of each sine component."
        @tier "domain"
      FOURIER_BURST -> external {
        particles : [RiyaFourierFx]
      }
        @description "Particle batch spawned on harmonic-pad narrative beats; fx-particles fades it."
        @tier "domain"
    }

    listens {
      FOURIER_PICKED { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
    }

    config {
      zoneId : string = "fourier"
        @label "Zone Id"
        @description "The zone this challenge choreography belongs to. Guards compare it against @entity.zoneId, so a composed open world fires it only while riya stands in this zone; standalone the entity default equals this knob and the guard is always true."
        @tier "domain"
    }
  }

  trait RiyaFourierClear -> @rebindable RiyaFourierState [interaction, instance] {
    initial: watching

    state watching {
      INIT -> watching
        (render-ui overlay null)

      RIYA_LEVEL_SOLVED -> watching
        (render-ui overlay {
          type: game-menu
          title: @config.clearTitle
          subtitle: @config.clearSubtitle
          options: [ { id: "next", label: "Next ▶", event: "FOURIER_NEXT", variant: "primary" } ]
        })

      FOURIER_NEXT -> watching
        (render-ui overlay null)
        (navigate @config.nextPath)

      CLOSE -> watching
        (render-ui overlay null)
    }

    listens {
      RIYA_LEVEL_SOLVED { level : string }
      FOURIER_NEXT { id : string }
      CLOSE
    }

    config {
      nextPath : string = "/riya-fourier"
        @label "Next Path"
        @description "Page the clear overlay's Next button navigates to. Standalone default replays this world; riya-game-platformer overrides it with the next world's path."
        @tier "presentation"
      clearTitle : string = "Fourier clear ★"
        @label "Clear Title"
        @description "Overlay title once every star is collected."
        @tier "presentation"
      clearSubtitle : string = "You rode the sum of sine waves — a square wave built one harmonic at a time."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
    }
  }

  page "/riya-fourier" as RiyaFourierPage -> FourierLevelData, FourierBody, FourierGate, FourierFx, FourierPickup, FourierTutorial, RiyaFourierGenre, RiyaFourierPlay, FourierChallenge, RiyaFourierClear
}
